import test from 'node:test';
import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {DesignAPI} from '../src/foundation.js';
import {Site} from '../src/site.js';
import {Resources} from '../src/resources.js';
import {emptyProject,tag,writeNBT,readNBT,importNBT,exportNBT} from '../src/codec.js';
const setup=()=>{const site=new Site({...emptyProject(),size:[50,50,50],origin:[-100,64,-200],metadata:{originConfirmed:true},palette:[{Name:'minecraft:stone'}],blocks:[{pos:[1,0,1],state:0}]});return{site,api:new DesignAPI({getSite:()=>site,resources:()=>new Resources()})};};
test('free design accepts new block IDs, paginated exact reads and negative world coordinates',()=>{const{site,api}=setup();const request={id:'free-1',method:'edit.apply',params:{expectedRevision:0,space:'world',operations:[{type:'set',pos:[-98,66,-198],state:{Name:'future_mod:sculpture',Properties:{variant:'custom'}}}]}};assert.ok(api.execute(request).ok);assert.equal(api.revision,1);assert.ok(api.execute(request).ok);assert.equal(api.revision,1);assert.equal(site.undo.length,1);const cells=api.execute({method:'scene.getBlocks',params:{positions:[[-98,66,-198]],space:'world'}});assert.equal(cells.value[0].state.Name,'future_mod:sculpture');const first=api.execute({method:'scene.readRegion',params:{min:[0,0,0],max:[4,4,4],limit:1,expectedRevision:1}});assert.equal(first.value.total,2);assert.equal(first.value.nextCursor,'1');assert.equal(api.execute({method:'scene.readRegion',params:{min:[0,0,0],max:[4,4,4],limit:1,cursor:'1'}}).value.blocks[0].state.Name,'future_mod:sculpture');assert.equal(api.execute({...request,params:{...request.params,operations:[]}}).error.code,'REQUEST_ID_REUSED');});
test('multi-batch transaction is isolated, atomic and a single undo',()=>{const{site,api}=setup();const begin=api.execute({id:'tx-start',method:'transaction.begin',params:{expectedRevision:0}}),transactionId=begin.value.transactionId;assert.equal(api.execute({id:'tx-start',method:'transaction.begin',params:{expectedRevision:0}}).value.transactionId,transactionId);for(const x of [3,4])assert.ok(api.execute({method:'transaction.apply',params:{transactionId,operations:[{type:'set',pos:[x,2,2],state:{Name:'minecraft:bricks'}}]}}).ok);assert.equal(site.overlay.size,0);assert.equal(api.execute({method:'scene.getBlocks',params:{transactionId,positions:[[3,2,2]]}}).value[0].state.Name,'minecraft:bricks');assert.ok(api.execute({method:'transaction.commit',params:{transactionId}}).ok);assert.equal(site.overlay.size,2);assert.equal(site.undo.length,1);assert.ok(api.execute({method:'history.undo',params:{expectedRevision:1}}).ok);assert.equal(site.overlay.size,0);});
test('stale commits and cell preconditions reject edits without partial changes',()=>{const{site,api}=setup();const transactionId=api.execute({method:'transaction.begin',params:{expectedRevision:0}}).value.transactionId;api.execute({method:'edit.apply',params:{expectedRevision:0,operations:[{type:'set',pos:[2,2,2],state:{Name:'minecraft:bricks'}}]}});assert.equal(api.execute({method:'transaction.commit',params:{transactionId}}).error.code,'REVISION_CONFLICT');assert.equal(api.execute({method:'edit.apply',params:{expectedRevision:1,operations:[{type:'set',pos:[2,2,2],expect:null,state:{Name:'minecraft:glass'}}]}}).error.code,'CELL_CONFLICT');assert.equal(site.at([2,2,2]).state,site.states.get('minecraft:bricks[]'));});
test('terrain locks apply to staging and arbitrary object grouping needs no template',()=>{const{site,api}=setup();const transactionId=api.execute({method:'transaction.begin',params:{expectedRevision:0}}).value.transactionId;assert.equal(api.execute({method:'transaction.apply',params:{transactionId,operations:[{type:'set',pos:[4,4,4],state:{Name:'minecraft:bricks'}},{type:'erase',min:[1,0,1],max:[1,0,1]}]}}).ok,false);assert.equal(api.transactions.get(transactionId).site.overlay.size,0);assert.ok(api.execute({method:'objects.put',params:{expectedRevision:0,object:{name:'自由曲面',cells:[[3,4,5],[6,7,8]]}}}).ok);assert.deepEqual(api.execute({method:'objects.list'}).value[0].cells,[[3,4,5],[6,7,8]]);assert.equal(site.design.objects.length,1);});
test('same-state block entity updates persist, dirty the cell, and undo restores NBT',()=>{const{site,api}=setup();site.base.blocks[0].nbt=tag(10,{Speed:tag(5,16)});const updated=tag(10,{Speed:tag(5,-16)});assert.ok(api.execute({method:'edit.apply',params:{expectedRevision:0,policy:{allowTerrain:true},operations:[{type:'set',pos:[1,0,1],state:{Name:'minecraft:stone'},nbt:updated}]}}).ok);assert.equal(site.at([1,0,1]).nbt.v.Speed.v,-16);assert.deepEqual(site.changedPositions,[[1,0,1]]);site.restore('undo');assert.equal(site.at([1,0,1]).nbt.v.Speed.v,16);});
test('Create blueprint skip masks and explicit air survive full NBT roundtrip',()=>{const root=tag(10,{DataVersion:tag(3,3955),size:tag(9,[3,[3,1,1]]),palette:tag(9,[10,[{Name:tag(8,'minecraft:stone')},{Name:tag(8,'minecraft:structure_void')},{Name:tag(8,'minecraft:air')}]]),blocks:tag(9,[10,[0,1,2].map(i=>({pos:tag(9,[3,[i,0,0]]),state:tag(3,i)}))]),entities:tag(9,[10,[]])}),p=importNBT(writeNBT(root),'synthetic');assert.equal(p.blocks.length,1);assert.equal(p.metadata.placementMask.skipCount,1);assert.equal(p.metadata.placementMask.eraseCount,1);assert.deepEqual(importNBT(exportNBT(p)).metadata.placementMask,p.metadata.placementMask);});
